from hypothesis import given, strategies as st
import pytest


def humanize(word: str) -> str:
    """
    Capitalize the first word and turn underscores into spaces and strip a
    trailing ``"_id"``, if any. Like :func:`titleize`, this is meant for
    creating pretty output.

    Examples::

        >>> humanize("employee_salary")
        'Employee salary'
        >>> humanize("author_id")
        'Author'

    """
    import re
    word = re.sub('_id$', '', word)
    word = word.replace('_', ' ')
    word = re.sub('(?i)([a-z\\d]*)', lambda m: m.group(1).lower(), word)
    word = re.sub('^\\w', lambda m: m.group(0).upper(), word)
    return word


@given(word=st.text(alphabet=st.sampled_from('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'), min_size=0, max_size=50))
def test_idempotence(word):
    assert humanize(humanize(word)) == humanize(word)


@given(word=st.text(alphabet=st.sampled_from('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'), min_size=0, max_size=50))
def test_metamorphic(word):
    assert humanize(word.upper()) == humanize(word)
    assert humanize(word.lower()) == humanize(word)


@given(word=st.text(alphabet=st.sampled_from('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'), min_size=0, max_size=50))
def test_value_postcondition_first_char_upper(word):
    result = humanize(word)
    if result:
        assert result[0] == result[0].upper()


@given(word=st.text(alphabet=st.sampled_from('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'), min_size=0, max_size=50))
def test_value_postcondition_no_underscores(word):
    assert '_' not in humanize(word)


@given(word=st.text(alphabet=st.sampled_from('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'), min_size=0, max_size=50))
def test_value_postcondition_no_trailing_id(word):
    result = humanize(word)
    assert not result.endswith('_id')
    assert not result.endswith(' id')


@given(word=st.text(alphabet=st.sampled_from('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'), min_size=0, max_size=50))
def test_type_postcondition(word):
    assert isinstance(humanize(word), str)

from hypothesis import given, strategies as st
import pytest


def first(iterable, default=None, key=None):
    """Return first element of *iterable* that evaluates to ``True``, else
    return ``None`` or optional *default*. Similar to :func:`one`.

    >>> first([0, False, None, [], (), 42])
    42
    >>> first([0, False, None, [], ()]) is None
    True
    >>> first([0, False, None, [], ()], default='ohai')
    'ohai'
    >>> import re
    >>> m = first(re.match(regex, 'abc') for regex in ['b.*', 'a(.*)'])
    >>> m.group(1)
    'bc'

    The optional *key* argument specifies a one-argument predicate function
    like that used for *filter()*.  The *key* argument, if supplied, should be
    in keyword form. For example, finding the first even number in an iterable:

    >>> first([1, 1, 3, 4, 5], key=lambda x: x % 2 == 0)
    4

    Contributed by Hynek Schlawack, author of `the original standalone module`_.

    .. _the original standalone module: https://github.com/hynek/first
    """
    return next(filter(key, iterable), default)


@given(
    iterable=st.one_of(st.lists(st.one_of(st.integers(), st.booleans(), st.none(), st.text(), st.floats(allow_nan=False))), st.lists(st.integers())),
    default=st.one_of(st.none(), st.integers(), st.text(), st.booleans(), st.floats(allow_nan=False)),
    key=st.one_of(st.none(), st.just(bool), st.just(lambda x: x is not None), st.just(lambda x: isinstance(x, int) and x % 2 == 0)),
)
def test_value_postcondition(iterable, default, key):
    result = first(iterable, default=default, key=key)
    assert result is default or result in iterable


@given(
    iterable=st.one_of(st.lists(st.one_of(st.integers(), st.booleans(), st.none(), st.text(), st.floats(allow_nan=False))), st.lists(st.integers())),
)
def test_value_postcondition_2(iterable):
    result = first(iterable, default=None)
    assert result is None or bool(result) is True


@given(
    iterable=st.one_of(st.lists(st.one_of(st.integers(), st.booleans(), st.none(), st.text(), st.floats(allow_nan=False))), st.lists(st.integers())),
    key=st.one_of(st.just(bool), st.just(lambda x: x is not None), st.just(lambda x: isinstance(x, int) and x % 2 == 0)),
)
def test_value_postcondition_3(iterable, key):
    result = first(iterable, default=None, key=key)
    assert result is None or key(result) is True


@given(
    iterable=st.one_of(st.lists(st.one_of(st.integers(), st.booleans(), st.none(), st.text(), st.floats(allow_nan=False))), st.lists(st.integers())),
)
def test_metamorphic(iterable):
    v = first(iterable, default=None)
    if v is not None:
        assert first([v] + list(iterable), default=None) == v


@given(
    iterable=st.one_of(st.lists(st.one_of(st.integers(), st.booleans(), st.none(), st.text(), st.floats(allow_nan=False))), st.lists(st.integers())),
    default=st.one_of(st.none(), st.integers(), st.text(), st.booleans(), st.floats(allow_nan=False)),
    key=st.one_of(st.none(), st.just(bool), st.just(lambda x: x is not None), st.just(lambda x: isinstance(x, int) and x % 2 == 0)),
)
def test_totality(iterable, default, key):
    first(iterable, default=default, key=key)

from hypothesis import given, strategies as st
import pytest


def under2camel(under_string):
    """Converts an underscored string to camelcased. Useful for turning a
    function name into a class name.

    >>> under2camel('complex_tokenizer')
    'ComplexTokenizer'
    """
    return ''.join((w.capitalize() or '_' for w in under_string.split('_')))


@given(under_string=st.text(alphabet=st.sampled_from('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_'), min_size=0))
def test_type_postcondition(under_string):
    assert isinstance(under2camel(under_string), str)


@given(under_string=st.text(alphabet=st.sampled_from('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_'), min_size=1).filter(lambda s: not s.startswith('_')))
def test_value_postcondition(under_string):
    result = under2camel(under_string)
    assert result[0].isupper()


@given(under_string=st.text(alphabet=st.sampled_from('abcdefghijklmnopqrstuvwxyz_'), min_size=0))
def test_metamorphic(under_string):
    assert under2camel(under_string.lower()) == under2camel(under_string.upper())


@given(under_string=st.text(alphabet=st.sampled_from('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_'), min_size=0))
def test_invariant_preservation(under_string):
    result = under2camel(under_string)
    assert result.replace('_', '').lower() == under_string.replace('_', '').lower()


@given(under_string=st.text(alphabet=st.sampled_from('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_'), min_size=0))
def test_totality(under_string):
    under2camel(under_string)

from hypothesis import given, strategies as st
import pytest
from inflection import underscore


def camelize(string: str, uppercase_first_letter: bool=True) -> str:
    """
    Convert strings to CamelCase.

    Examples::

        >>> camelize("device_type")
        'DeviceType'
        >>> camelize("device_type", False)
        'deviceType'

    :func:`camelize` can be thought of as a inverse of :func:`underscore`,
    although there are some cases where that does not hold::

        >>> camelize(underscore("IOError"))
        'IoError'

    :param uppercase_first_letter: if set to `True` :func:`camelize` converts
        strings to UpperCamelCase. If set to `False` :func:`camelize` produces
        lowerCamelCase. Defaults to `True`.
    """
    import re
    if uppercase_first_letter:
        return re.sub('(?:^|_)(.)', lambda m: m.group(1).upper(), string)
    else:
        return string[0].lower() + camelize(string)[1:]


@given(string=st.from_regex(r'[a-z][a-z0-9]*(_[a-z][a-z0-9]*)*', fullmatch=True))
def test_round_trip_snake_to_camel(string):
    # camelize(underscore(s)) == s for typical CamelCase strings
    # Here we test underscore then camelize round-trip on snake_case input
    assert camelize(underscore(camelize(string)), True) == camelize(string, True)


@given(string=st.from_regex(r'[A-Z][a-z0-9]*([A-Z][a-z0-9]*)*', fullmatch=True))
def test_round_trip_camel_to_snake(string):
    # underscore(camelize(s)) == s for typical CamelCase strings
    assert underscore(camelize(underscore(string))) == underscore(string)


@given(string=st.one_of(
    st.text(alphabet=st.characters(whitelist_categories=('Ll', 'Lu', 'Nd'), whitelist_characters='_'), min_size=0),
    st.from_regex(r'[a-z][a-z0-9]*(_[a-z][a-z0-9]*)*', fullmatch=True),
    st.from_regex(r'[A-Z][a-z0-9]*([A-Z][a-z0-9]*)*', fullmatch=True)
))
def test_idempotence(string):
    assert camelize(camelize(string, True), True) == camelize(string, True)


@given(string=st.one_of(
    st.text(alphabet=st.characters(whitelist_categories=('Ll', 'Lu', 'Nd'), whitelist_characters='_'), min_size=1),
    st.from_regex(r'[a-z][a-z0-9]*(_[a-z][a-z0-9]*)*', fullmatch=True),
    st.from_regex(r'[A-Z][a-z0-9]*([A-Z][a-z0-9]*)*', fullmatch=True)
))
def test_value_postcondition_uppercase_first(string):
    result = camelize(string, True)
    # Only check if result is non-empty and first char is alphabetic
    if result and result[0].isalpha():
        assert result[0] == result[0].upper()


@given(string=st.from_regex(r'[a-z][a-z0-9]*(_[a-z][a-z0-9]*)*', fullmatch=True))
def test_value_postcondition_no_underscores(string):
    # '_' not in camelize(s, True) for strings where underscores only appear as separators
    result = camelize(string, True)
    assert '_' not in result

from hypothesis import given, strategies as st
import pytest


def dasherize(word: str) -> str:
    """Replace underscores with dashes in the string.

    Example::

        >>> dasherize("puni_puni")
        'puni-puni'

    """
    return word.replace('_', '-')


@given(word=st.text())
def test_idempotence(word):
    assert dasherize(dasherize(word)) == dasherize(word)


@given(word=st.text())
def test_invariant_preservation(word):
    assert len(dasherize(word)) == len(word)


@given(word=st.text())
def test_metamorphic(word):
    assert '_' not in dasherize(word)


@given(word=st.text())
def test_type_postcondition(word):
    assert isinstance(dasherize(word), str)

from hypothesis import given, strategies as st
import pytest


def ordinal(number: int) -> str:
    """
    Return the suffix that should be added to a number to denote the position
    in an ordered sequence such as 1st, 2nd, 3rd, 4th.

    Examples::

        >>> ordinal(1)
        'st'
        >>> ordinal(2)
        'nd'
        >>> ordinal(1002)
        'nd'
        >>> ordinal(1003)
        'rd'
        >>> ordinal(-11)
        'th'
        >>> ordinal(-1021)
        'st'

    """
    number = abs(int(number))
    if number % 100 in (11, 12, 13):
        return 'th'
    else:
        return {1: 'st', 2: 'nd', 3: 'rd'}.get(number % 10, 'th')


@given(number=st.integers())
def test_type_postcondition(number):
    assert isinstance(ordinal(number), str)


@given(number=st.integers())
def test_value_postcondition(number):
    assert ordinal(number) in ('st', 'nd', 'rd', 'th')


@given(number=st.integers())
def test_metamorphic_negation(number):
    assert ordinal(number) == ordinal(-number)


@given(number=st.integers())
def test_metamorphic_periodicity(number):
    assert ordinal(number) == ordinal(number + 100)


@given(number=st.integers())
def test_totality(number):
    ordinal(number)

from hypothesis import given, strategies as st
import pytest


def transliterate(string: str) -> str:
    """
    Replace non-ASCII characters with an ASCII approximation. If no
    approximation exists, the non-ASCII character is ignored. The string must
    be ``unicode``.

    Examples::

        >>> transliterate('älämölö')
        'alamolo'
        >>> transliterate('Ærøskøbing')
        'rskbing'

    """
    import unicodedata
    normalized = unicodedata.normalize('NFKD', string)
    return normalized.encode('ascii', 'ignore').decode('ascii')


@given(string=st.text())
def test_idempotence(string):
    assert transliterate(transliterate(string)) == transliterate(string)


@given(string=st.text())
def test_value_postcondition(string):
    assert transliterate(string).isascii() == True


@given(string=st.text())
def test_invariant_preservation(string):
    assert len(transliterate(string)) <= len(string)


@given(string=st.text())
def test_type_postcondition(string):
    assert isinstance(transliterate(string), str)


@given(string=st.text(), string2=st.text())
def test_metamorphic(string, string2):
    assert transliterate(string + string2) == transliterate(string) + transliterate(string2)

from hypothesis import given, strategies as st
import pytest
from inflection import camelize


def underscore(word: str) -> str:
    """
    Make an underscored, lowercase form from the expression in the string.

    Example::

        >>> underscore("DeviceType")
        'device_type'

    As a rule of thumb you can think of :func:`underscore` as the inverse of
    :func:`camelize`, though there are cases where that does not hold::

        >>> camelize(underscore("IOError"))
        'IoError'

    """
    import re
    word = re.sub('([A-Z]+)([A-Z][a-z])', '\\1_\\2', word)
    word = re.sub('([a-z\\d])([A-Z])', '\\1_\\2', word)
    word = word.replace('-', '_')
    return word.lower()


@given(word=st.from_regex(r'[A-Za-z][A-Za-z0-9]*(?:[_\-/ ][A-Za-z][A-Za-z0-9]*)*', fullmatch=True))
def test_idempotence(word):
    assert underscore(underscore(word)) == underscore(word)


@given(word=st.from_regex(r'[A-Za-z][A-Za-z0-9]*(?:[_\-/ ][A-Za-z][A-Za-z0-9]*)*', fullmatch=True))
def test_value_postcondition_lowercase(word):
    result = underscore(word)
    assert result.lower() == result


@given(word=st.from_regex(r'[A-Za-z][A-Za-z0-9]*(?:[_\-/ ][A-Za-z][A-Za-z0-9]*)*', fullmatch=True))
def test_value_postcondition_no_dash(word):
    assert '-' not in underscore(word)


@given(word=st.from_regex(r'[a-z][a-z0-9]*(?:[_][a-z][a-z0-9]*)*', fullmatch=True))
def test_metamorphic_lowercase_unchanged(word):
    # For already-lowercase snake_case input, lowercasing first makes no difference
    assert underscore(word.lower()) == underscore(word)


@given(word=st.from_regex(r'[A-Za-z][A-Za-z0-9]*(?:[_\-/ ][A-Za-z][A-Za-z0-9]*)*', fullmatch=True))
def test_type_postcondition(word):
    assert isinstance(underscore(word), str)


@given(word=st.from_regex(r'[a-z][a-z0-9]*(?:_[a-z][a-z0-9]*)*', fullmatch=True))
def test_round_trip(word):
    # underscore(camelize(s)) == s holds for simple snake_case strings
    assert underscore(camelize(word)) == word
